@@ -0,0 +1,41 @@
+package de.stephanlindauer.criticalmaps.utils;
+
+import androidx.annotation.Nullable;
+
+import java.io.UnsupportedEncodingException;
+import java.security.MessageDigest;
+import java.security.NoSuchAlgorithmException;
+import java.util.Arrays;
+
+public class AeSimpleSHA256 {
+
+    // Number of digest bytes kept, so the hex string stays 40 characters long as before.
+    private static final int OUTPUT_BYTES = 20;
+
+    @Nullable
+    public static String truncatedSHA256(String text) {
+        try {
+            final MessageDigest md = MessageDigest.getInstance("SHA-256");
+            //noinspection CharsetObjectCanBeUsed - NOTE fix not applicable on API16
+            md.update(text.getBytes("iso-8859-1"), 0, text.length());
+            final byte[] hash = md.digest();
+            return convertToHex(Arrays.copyOf(hash, OUTPUT_BYTES));
+        } catch (NoSuchAlgorithmException | UnsupportedEncodingException e) {
+            e.printStackTrace();
+            return null;
+        }
+    }
+
+    private static String convertToHex(byte[] data) {
+        StringBuilder buf = new StringBuilder();
+        for (byte b : data) {
+            int halfbyte = (b >>> 4) & 0x0F;
+            int two_halfs = 0;
+            do {
+                buf.append((0 <= halfbyte) && (halfbyte <= 9) ? (char) ('0' + halfbyte) : (char) ('a' + (halfbyte - 10)));
+                halfbyte = b & 0x0F;
+            } while (two_halfs++ < 1);
+        }
+        return buf.toString();
+    }
+}
