new file mode 100644
index 00000000..35a9427d
--- /dev/null
+++ b/app/src/test/java/me/ash/reader/infrastructure/di/OkHttpClientModuleTest.kt
@@ -0,0 +1,84 @@
+package me.ash.reader.infrastructure.di
+
+import android.content.Context
+import okhttp3.Request
+import okhttp3.mockwebserver.MockResponse
+import okhttp3.mockwebserver.MockWebServer
+import okhttp3.tls.HandshakeCertificates
+import okhttp3.tls.HeldCertificate
+import org.junit.Assert.assertEquals
+import org.junit.Assert.assertThrows
+import org.junit.Test
+import org.junit.runner.RunWith
+import org.junit.runners.Parameterized
+import org.mockito.kotlin.mock
+import javax.net.ssl.SSLHandshakeException
+import javax.net.ssl.SSLPeerUnverifiedException
+
+@RunWith(Parameterized::class)
+class OkHttpClientModuleTest(private val clientCertificateAlias: String?) {
+
+    companion object {
+        @JvmStatic
+        @Parameterized.Parameters(name = "client certificate alias: {0}")
+        fun aliases(): List<Array<String?>> = listOf(arrayOf(null), arrayOf("test-client"))
+    }
+
+    private fun client() = cachingHttpClient(
+        context = mock<Context>(),
+        clientCertificateAlias = clientCertificateAlias,
+    )
+
+    @Test
+    fun rejectsUntrustedServerCertificate() {
+        val certificate = certificateFor("localhost")
+        server(certificate).use { server ->
+            val request = Request.Builder().url(server.url("/")).build()
+            assertThrows(SSLHandshakeException::class.java) {
+                client().newCall(request).execute().close()
+            }
+        }
+    }
+
+    @Test
+    fun rejectsTrustedCertificateForAnotherHostname() {
+        val certificate = certificateFor("another.example")
+        server(certificate).use { server ->
+            val request = Request.Builder().url(server.url("/")).build()
+            assertThrows(SSLPeerUnverifiedException::class.java) {
+                clientTrusting(certificate).newCall(request).execute().close()
+            }
+        }
+    }
+
+    @Test
+    fun acceptsTrustedCertificateForMatchingHostname() {
+        val certificate = certificateFor("localhost")
+        server(certificate).use { server ->
+            val request = Request.Builder().url(server.url("/")).build()
+            clientTrusting(certificate).newCall(request).execute().use { response ->
+                assertEquals("ok", response.body.string())
+            }
+        }
+    }
+
+    private fun certificateFor(hostname: String) = HeldCertificate.Builder()
+        .commonName(hostname)
+        .addSubjectAlternativeName(hostname)
+        .build()
+
+    private fun server(certificate: HeldCertificate): MockWebServer {
+        val certificates = HandshakeCertificates.Builder().heldCertificate(certificate).build()
+        return MockWebServer().apply {
+            useHttps(certificates.sslSocketFactory(), false)
+            enqueue(MockResponse().setBody("ok"))
+            start()
+        }
+    }
+
+    private fun clientTrusting(certificate: HeldCertificate) =
+        HandshakeCertificates.Builder().addTrustedCertificate(certificate.certificate).build().let {
+            // Trust the local test certificate while retaining the app's hostname verifier.
+            client().newBuilder().sslSocketFactory(it.sslSocketFactory(), it.trustManager).build()
+        }
+}
