@@ -0,0 +1,16 @@
+package com.philkes.notallyx.utils
+
+import java.io.ByteArrayInputStream
+import org.junit.Assert.assertEquals
+import org.junit.Test
+
+class HashTest {
+    @Test
+    fun sha256HashesAcrossMultipleBuffers() {
+        val input = ByteArrayInputStream(ByteArray(1_000_000) { 'a'.code.toByte() })
+
+        val hash = input.sha256Hash().joinToString("") { "%02x".format(it) }
+
+        assertEquals("cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0", hash)
+    }
+}

