new file mode 100644
index 0000000..2d93b5d
--- /dev/null
+++ b/app/src/test/kotlin/com/philkes/notallyx/utils/HashTest.kt
@@ -0,0 +1,30 @@
+package com.philkes.notallyx.utils
+
+import org.junit.Assert.assertArrayEquals
+import org.junit.Assert.assertFalse
+import org.junit.Test
+
+class HashTest {
+    @Test
+    fun sha256MatchesKnownDigest() {
+        val expected =
+            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
+                .chunked(2)
+                .map { it.toInt(16).toByte() }
+                .toByteArray()
+
+        assertArrayEquals(expected, "abc".byteInputStream().sha256Hash())
+    }
+
+    @Test
+    fun sha256DistinguishesChangedCopyAcrossBuffers() {
+        val source = ByteArray(300_000) { (it % 251).toByte() }
+        val copy = source.copyOf()
+        assertArrayEquals(source.inputStream().sha256Hash(), copy.inputStream().sha256Hash())
+
+        copy[copy.lastIndex] = (copy.last() + 1).toByte()
+        assertFalse(
+            source.inputStream().sha256Hash().contentEquals(copy.inputStream().sha256Hash())
+        )
+    }
+}

