@@ -0,0 +1,103 @@
+package com.philkes.notallyx.utils
+
+import java.io.ByteArrayInputStream
+import java.io.InputStream
+import org.junit.Assert.assertArrayEquals
+import org.junit.Assert.assertEquals
+import org.junit.Assert.assertFalse
+import org.junit.Assert.assertTrue
+import org.junit.Rule
+import org.junit.Test
+import org.junit.rules.TemporaryFolder
+
+class IOExtensionsDigestTest {
+    @get:Rule
+    val temporaryFolder = TemporaryFolder()
+
+    @Test
+    fun knownStreamVectors() {
+        assertEquals(EMPTY_SHA256, byteArrayOf().inputStream().sha256Hash().toHex())
+        assertEquals(ABC_SHA256, "abc".toByteArray(Charsets.UTF_8).inputStream().sha256Hash().toHex())
+    }
+
+    @Test
+    fun knownFileVectors() {
+        val empty = temporaryFolder.newFile("empty")
+        val abc = temporaryFolder.newFile("abc")
+        abc.writeBytes("abc".toByteArray(Charsets.UTF_8))
+
+        assertEquals(EMPTY_SHA256, empty.sha256Hash().toHex())
+        assertEquals(ABC_SHA256, abc.sha256Hash().toHex())
+    }
+
+    @Test
+    fun zeroReadsBeforeDataAndEofDoNotChangeDigest() {
+        val stream = ZeroBeforeDataAndEofInputStream("abc".toByteArray(Charsets.UTF_8))
+
+        assertEquals(ABC_SHA256, stream.sha256Hash().toHex())
+        assertTrue(stream.returnedZeroBeforeData)
+        assertTrue(stream.returnedZeroBeforeEof)
+        assertTrue(stream.closed)
+    }
+
+    @Test
+    fun zeroReadsBeforeEmptyStreamEofDoNotChangeDigest() {
+        val stream = ZeroBeforeDataAndEofInputStream(byteArrayOf())
+
+        assertEquals(EMPTY_SHA256, stream.sha256Hash().toHex())
+        assertTrue(stream.returnedZeroBeforeData)
+        assertTrue(stream.returnedZeroBeforeEof)
+        assertTrue(stream.closed)
+    }
+
+    @Test
+    fun independentlyHashedCopiesCompareByContent() {
+        val source = "matching content".toByteArray(Charsets.UTF_8)
+        val copy = temporaryFolder.newFile("copy")
+        val modified = temporaryFolder.newFile("modified")
+        copy.writeBytes(source.copyOf())
+        modified.writeBytes("matching content!".toByteArray(Charsets.UTF_8))
+
+        val sourceDigest = source.inputStream().sha256Hash()
+        assertArrayEquals(sourceDigest, copy.sha256Hash())
+        assertFalse(sourceDigest.contentEquals(modified.sha256Hash()))
+    }
+
+    private fun ByteArray.toHex(): String =
+        joinToString("") { "%02x".format(it.toInt() and 0xff) }
+
+    private class ZeroBeforeDataAndEofInputStream(bytes: ByteArray) : InputStream() {
+        private val delegate = ByteArrayInputStream(bytes)
+        var returnedZeroBeforeData = false
+            private set
+        var returnedZeroBeforeEof = false
+            private set
+        var closed = false
+            private set
+
+        override fun read(): Int = delegate.read()
+
+        override fun read(buffer: ByteArray, offset: Int, length: Int): Int {
+            if (length == 0) return 0
+            if (!returnedZeroBeforeData) {
+                returnedZeroBeforeData = true
+                return 0
+            }
+            if (delegate.available() == 0 && !returnedZeroBeforeEof) {
+                returnedZeroBeforeEof = true
+                return 0
+            }
+            return delegate.read(buffer, offset, length)
+        }
+
+        override fun close() {
+            closed = true
+            delegate.close()
+        }
+    }
+
+    private companion object {
+        const val EMPTY_SHA256 = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
+        const val ABC_SHA256 = "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
+    }
+}
